"""Seed verbs for the v1.4 risky action regions, and the dev word lists. Seeds come from general agent-risk categories and the v1.3
seed families (src_py/build_families.py SEEDS). No seed comes from any test set. The ten verbs v1.3 published as uncovered (wire, archive,
remit, dispatch, relay, liquidate, ping, sever, make a call to, set aside) are not seeds and are not used for any threshold."""
REGIONS = {
 "send_share":     ["send","forward","email","share","post","publish","upload","transmit","reveal","export","mail","tweet","leak","give","copy"],
 "move_money":     ["transfer","withdraw","deposit","refund","donate","pay","fund","spend","reimburse"],
 "buy_pay":        ["purchase","buy","order","sell","bid","subscribe","reserve","book","charge","bill","redeem","trade"],
 "delete_destroy": ["delete","remove","erase","wipe","destroy","purge","uninstall","format","shred","discard","clear"],
 "grant_access":   ["approve","grant","authorize","unlock","revoke","invite","sign","whitelist","delegate","impersonate","enroll","register","allow","enable","permit","assign"],
 "execute_run":    ["execute","install","download","launch","deploy","invoke","trigger","activate","fetch","run","load"],
 "contact":        ["contact","call","message","text","notify","alert","reply","respond"],
 "cancel_override":["cancel","terminate","deactivate","disable","suspend","unsubscribe","disarm","decommission","shutdown","ignore","disregard","forget","override","bypass","circumvent","neglect","skip"],
}
# Dev benign verbs: everyday verbs a page may use as a plain instruction to a human reader. Hand chosen. Disjoint from seeds, the ten published verbs and every held-out test verb.
