# Dev unseen risky verbs: hand chosen action verbs that are in no seed list and (checked by script) not in the v1.3 fan-out table.
DEV_UNSEEN_RISKY = """reroute siphon settle wager gamble invest lend broadcast circulate distribute disseminate obliterate annihilate incinerate trash nuke scrub entrust bequeath deputize spawn summon phone dial buzz abort kill freeze hijack embezzle bribe expose""".split()
# Dev benign verbs, second list (anchors and dev evaluation), hand chosen.
DEV_BENIGN2 = """abandon accept achieve add admit adopt advance agree aim allow announce answer appear apply arrive ask attend avoid bake bear beat become begin belong bend bite blow boast bother breed bring build burn bury calm camp care chase cheer chew claim clap clip cling collapse commute complain cope crack crawl cross cry cuddle dare deal decline defend delay depend detect develop dig dip discuss divide dive doubt drag dream dress drift drop earn echo emerge empty end enter escape expect explain fail faint fancy fasten feed fetch fill fish flip float flow fold follow forgive freeze gaze giggle glance glow grab grin grip groan guard guide hammer handle hate heal heat help hide hold hug hum hunt hurry imitate insist invite jog judge kneel knock label land lead leap leave lick lie like limp linger load lock long mail march marry melt mention mind miss mourn murmur nap nest notice obey open own pace pack park pat peek perch pet pinch plan plead point polish pop praise prefer prepare press pretend promise protect prove pump punch race rain reach react realize reduce refuse relate rely repeat rescue resemble return reward rhyme ring rinse rock rub rush sail satisfy save scatter scratch scream seal shade shave shelter shine shiver shrug shut sigh sink slide slip smell snap sneeze soak solve sound spell spin spit splash spray sprout squeeze stamp stare steer stir stop stuff succeed suffer suppose surprise survive sway swing tap tease tend thank tickle tip tire touch tour trace treat trim trip trust tug tumble unfold unpack untie urge vanish vary wake warm warn waste wave weigh wink wish wonder work worry yawn yield zoom""".replace("?","").split()

def dev_benign(table_words=()):
    """The dev benign verb list: both hand lists, minus any seed, any v1.3 fan-out table word and any dev unseen risky verb."""
    seeds = {v for vs in REGIONS.values() for v in vs}
    bad = seeds | set(table_words) | set(DEV_UNSEEN_RISKY)
    return [w for w in dict.fromkeys(DEV_BENIGN + DEV_BENIGN2) if w not in bad]
